//! 🧶️ Shared OpenType lookup selection, substitution, marks, ligatures and cluster mapping agree with ttf-parser and rustybuzz through funded close.
use super::*;
use semio_framework_2d_text_font::*;
use semio_framework_2d_text_font_testing::{bytes,close,close_with_items};
#[global_allocator]
static FONT_HEAP:semio_framework_trace::HeapWitness=semio_framework_trace::HeapWitness;
fn original_context_coverages(sub:ttf_parser::gsub::SubstitutionSubtable<'_>)->(Vec<ttf_parser::opentype_layout::Coverage<'_>>,Vec<ttf_parser::opentype_layout::Coverage<'_>>,Vec<ttf_parser::opentype_layout::Coverage<'_>>,Vec<crate::context::FontSequenceLookup>){use ttf_parser::opentype_layout::{ContextLookup,ChainedContextLookup};match sub{ttf_parser::gsub::SubstitutionSubtable::Context(ContextLookup::Format3{coverage,coverages,lookups})=>(Vec::new(),std::iter::once(coverage).chain(coverages.into_iter()).collect(),Vec::new(),lookups.into_iter().map(|record|crate::context::FontSequenceLookup{sequence:usize::from(record.sequence_index),lookup:record.lookup_list_index}).collect()),ttf_parser::gsub::SubstitutionSubtable::ChainContext(ChainedContextLookup::Format3{coverage,backtrack_coverages,input_coverages,lookahead_coverages,lookups})=>(backtrack_coverages.into_iter().collect(),std::iter::once(coverage).chain(input_coverages.into_iter()).collect(),lookahead_coverages.into_iter().collect(),lookups.into_iter().map(|record|crate::context::FontSequenceLookup{sequence:usize::from(record.sequence_index),lookup:record.lookup_list_index}).collect()),_=>panic!("Shared original context source requires authored format corpus")}}
#[test]
fn font_shape_shared_original_context_records(){let rows:serde_json::Value=serde_json::from_str(include_str!("../🧩️context/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let mut matched=0;for row in rows.as_array().unwrap(){let mut admission=FontFaceAdmissionJob::new(bytes(row["font"].as_str().unwrap()),FontOutlineLimits::default());while !admission.advance(4096).unwrap().done{}let font=admission.take_result().unwrap();let parsed=ttf_parser::Face::parse(&font.source,0).unwrap();let table=parsed.tables().gsub.unwrap();let r=FontReader::new(&font.source,font.face.gsub.unwrap()).unwrap();let list=font.face.gsub.unwrap().offset+usize::from(r.u16(font.face.gsub.unwrap().offset+8).unwrap());for index in 0..table.lookups.len(){let lookup=table.lookups.get(index).unwrap();let offset=list+usize::from(r.u16(list+2+usize::from(index)*2).unwrap());let kind=r.u16(offset).unwrap();if u64::from(kind)!=row["kind"].as_u64().unwrap()||lookup.flags.0!=0{continue;}let actual=crate::FontLookup{index,kind,flags:0,offset,subtables:usize::from(lookup.subtables.len())};let candidates=(0..lookup.subtables.len()).map(|at|{let(back,input,ahead,_)=original_context_coverages(lookup.subtables.get(at).unwrap());let representative=|coverage:ttf_parser::opentype_layout::Coverage<'_>|(0..font.face.glyphs).find(|glyph|coverage.get(ttf_parser::GlyphId(*glyph)).is_some()).unwrap();let start=back.len();let glyphs=back.into_iter().rev().chain(input).chain(ahead).map(representative).collect::<Vec<_>>();(glyphs,start)}).collect::<Vec<_>>();for probe in row["probes"].as_array().unwrap(){let probe=probe.as_str().unwrap();let at=match probe{"middle"=>candidates.len()/2,"last"=>candidates.len()-1,_=>0};let(mut glyphs,start)=candidates[at].clone();if probe=="missing"{glyphs[start]=u16::MAX;}let expected=(0..lookup.subtables.len()).find_map(|at|{let(back,input,ahead,records)=original_context_coverages(lookup.subtables.get(at).unwrap());if back.len()>start||start+input.len()+ahead.len()>glyphs.len()||back.iter().enumerate().any(|(at,coverage)|coverage.get(ttf_parser::GlyphId(glyphs[start-at-1])).is_none())||input.iter().enumerate().any(|(at,coverage)|coverage.get(ttf_parser::GlyphId(glyphs[start+at])).is_none())||ahead.iter().enumerate().any(|(at,coverage)|coverage.get(ttf_parser::GlyphId(glyphs[start+input.len()+at])).is_none()){None}else{Some((input.len(),records))}});if probe=="first"{}let pointer=glyphs.as_ptr();for grant in [1,7,4096]{let mut cursor=crate::context::FontContextCursor::new(font.face,actual,&glyphs,start,1000000000);let mut work=0;loop{let progress=cursor.advance(&font.source,&glyphs,grant).unwrap();assert!(progress.work-work<=grant as u64);work=progress.work;if progress.done{break;}assert!(cursor.result().is_err());}let output=cursor.result().unwrap().map(|output|(output.input_count,output.records[..output.count].to_vec()));assert_eq!(output,expected);close(cursor);matched+=1;}for stop in [0,1,2,7,20,40,100]{let mut cursor=crate::context::FontContextCursor::new(font.face,actual,&glyphs,start,1000000000);if stop>0{cursor.advance(&font.source,&glyphs,stop).unwrap();}let(_,physical)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cursor.cancel());assert_eq!((physical.requested_bytes,physical.released_bytes),(0,0));assert!(cursor.result().is_err());close(cursor);assert_eq!(glyphs.as_ptr(),pointer);}close(glyphs);}}close(admission);close(font);}assert!(matched>0);}
