fn font_shape_original_composed_substitution(){use crate::face::*;use semio_framework_2d_text_font_shape_unicode::*;let rows:serde_json::Value=serde_json::from_str(include_str!("../🧵️layout/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let mut unicode_admission=UnicodeDataAdmissionJob::new(UNICODE_BYTES.to_vec(),1000000);while !unicode_admission.advance(4096).unwrap().done{}let data=unicode_admission.take_result().unwrap();for row in rows.as_array().unwrap(){let source=bytes(row["font"].as_str().unwrap());let mut admission=FontFaceAdmissionJob::new(source,FontOutlineLimits::default());while !admission.advance(4096).unwrap().done{}let font=admission.take_result().unwrap();let parser=ttf_parser::Face::parse(&font.source,0).unwrap();let text=row["text"].as_str().unwrap();let expected=row["glyphs"].as_array().unwrap().iter().map(|value|value.as_u64().unwrap()as u16).collect::<Vec<_>>();let mut buffer=rustybuzz::UnicodeBuffer::new();buffer.push_str(text);buffer.guess_segment_properties();let shaped=rustybuzz::shape(&rustybuzz::Face::from_slice(&font.source,0).unwrap(),&[],buffer);assert_eq!(shaped.glyph_infos().iter().map(|value|value.glyph_id as u16).collect::<Vec<_>>(),expected);let original=||FontClusterMapping{face:0,glyphs:text.char_indices().map(|(source_at,scalar)|{let mut property=UnicodePropertyCursor::new(data.layout,scalar as u32).unwrap();while !property.step(&data.source).unwrap(){}FontMappedScalar{glyph:parser.glyph_index(scalar).unwrap().0,scalar:scalar as u32,source_at,property:property.result().unwrap()}}).collect()};for grant in [1,7,4096]{let mapping=original();let input_pointer=mapping.glyphs.as_ptr();let mut cursor=crate::layout::FontClusterLayoutCursor::new(font.face,mapping,FontOutlineLimits::default());let mut work=0;loop{let p=cursor.advance(&font.source,grant).unwrap();assert!(p.work-work<=grant as u64);work=p.work;if p.done{break;}assert!(cursor.result().is_err());}let result=cursor.result().unwrap();assert_eq!(result.glyphs.iter().map(|value|value.glyph).collect::<Vec<_>>(),expected);let output_pointer=result.glyphs.as_ptr();let output=cursor.take_result().unwrap();assert_eq!(output.glyphs.as_ptr(),output_pointer);assert!(!input_pointer.is_null());close(cursor);assert_eq!(output.glyphs.iter().map(|value|value.glyph).collect::<Vec<_>>(),expected);close(output);}for stop in [0,1,2,7,20,40,100]{let mut cursor=crate::layout::FontClusterLayoutCursor::new(font.face,original(),FontOutlineLimits::default());if stop>0{cursor.advance(&font.source,stop).unwrap();}let(_,physical)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cursor.cancel());assert_eq!((physical.requested_bytes,physical.released_bytes),(0,0));assert!(cursor.result().is_err());close(cursor);}close(admission);close(font);}close(unicode_admission);close(data);}
