fn font_shape_original_gdef_eligibility(){let rows:serde_json::Value=serde_json::from_str(include_str!("../🏷️class/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let mut queries=0;for source in semio_framework_2d_text_font_catalog::FONT_SOURCES.iter(){let mut admission=FontFaceAdmissionJob::new(source.bytes,FontOutlineLimits::default());while !admission.advance(4096).unwrap().done{}let font=admission.take_result().unwrap();let parsed=ttf_parser::Face::parse(source.bytes.0,0).unwrap();for row in rows.as_array().unwrap(){for scalar in row["text"].as_str().unwrap().chars(){let glyph=parsed.glyph_index(scalar).unwrap_or(ttf_parser::GlyphId(0));let expected=parsed.tables().gdef.and_then(|table|table.glyph_class(glyph)).map_or(0,|class|match class{ttf_parser::gdef::GlyphClass::Base=>1,ttf_parser::gdef::GlyphClass::Ligature=>2,ttf_parser::gdef::GlyphClass::Mark=>3,ttf_parser::gdef::GlyphClass::Component=>4});let mut cursor=crate::class::FontGlyphClassCursor::new(font.face,glyph.0).unwrap();let mut turns=0;while !cursor.step(source.bytes.0).unwrap(){assert!(cursor.result().is_err());turns+=1;assert!(turns<100);}assert_eq!(cursor.result().unwrap(),expected);close(cursor);queries+=1;}}close(admission);close(font);}}
