fn font_shape_single_multiple_original_substitutions(){let rows:serde_json::Value=serde_json::from_str(include_str!("../🪄️substitute/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let mut matched=0;for source in semio_framework_2d_text_font_catalog::FONT_SOURCES.iter(){let mut admission=FontFaceAdmissionJob::new(source.bytes,FontOutlineLimits::default());while !admission.advance(4096).unwrap().done{}let font=admission.take_result().unwrap();let parsed=ttf_parser::Face::parse(source.bytes.0,0).unwrap();if let Some(table)=parsed.tables().gsub{let r=FontReader::new(source.bytes.0,font.face.gsub.unwrap()).unwrap();let list=font.face.gsub.unwrap().offset+usize::from(r.u16(font.face.gsub.unwrap().offset+8).unwrap());for index in 0..table.lookups.len(){let lookup=table.lookups.get(index).unwrap();let offset=list+usize::from(r.u16(list+2+usize::from(index)*2).unwrap());let kind=r.u16(offset).unwrap();let Some(row)=rows.as_array().unwrap().iter().find(|row|row["kind"].as_u64()==Some(u64::from(kind)))else{continue;};if lookup.flags.0!=0{continue;}let actual=crate::FontLookup{index,kind,flags:lookup.flags.0,offset,subtables:usize::from(lookup.subtables.len())};let first=lookup.subtables.get::<ttf_parser::gsub::SubstitutionSubtable>(0).unwrap();let covered=(0..font.face.glyphs).filter(|glyph|first.coverage().get(ttf_parser::GlyphId(*glyph)).is_some()).collect::<Vec<_>>();for probe in row["probes"].as_array().unwrap(){let glyph=match probe.as_str().unwrap(){"first"=>covered[0],"middle"=>covered[covered.len()/2],"last"=>*covered.last().unwrap(),_=>65535};let expected=(0..lookup.subtables.len()).find_map(|sub|{let sub=lookup.subtables.get::<ttf_parser::gsub::SubstitutionSubtable>(sub).unwrap();match sub{ttf_parser::gsub::SubstitutionSubtable::Single(table)=>table.coverage().get(ttf_parser::GlyphId(glyph)).map(|coverage|match table{ttf_parser::gsub::SingleSubstitution::Format1{delta,..}=>vec![glyph.wrapping_add(delta as u16)],ttf_parser::gsub::SingleSubstitution::Format2{substitutes,..}=>vec![substitutes.get(coverage).unwrap().0]}),ttf_parser::gsub::SubstitutionSubtable::Multiple(table)=>table.coverage.get(ttf_parser::GlyphId(glyph)).map(|coverage|table.sequences.get(coverage).unwrap().substitutes.into_iter().map(|glyph|glyph.0).collect::<Vec<_>>()),_=>panic!("Unexpected original substitution kind")}});for grant in [1,7,4096]{let mut cursor=crate::substitute::FontSubstitutionCursor::new(font.face,actual,glyph,1000000000);let mut work=0;loop{let p=cursor.advance(source.bytes.0,grant).unwrap();assert!(p.work-work<=grant as u64);work=p.work;if p.done{break;}assert!(cursor.result().is_err());}let result=cursor.result().unwrap().map(|result|result.glyphs[..result.count].to_vec());assert_eq!(result,expected);close(cursor);matched+=1;}for stop in [0,1,2,7,20,40,100]{let mut cursor=crate::substitute::FontSubstitutionCursor::new(font.face,actual,glyph,1000000000);if stop>0{cursor.advance(source.bytes.0,stop).unwrap();}let(_,physical)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cursor.cancel());assert_eq!((physical.requested_bytes,physical.released_bytes),(0,0));assert!(cursor.result().is_err());close(cursor);}}}}close(admission);close(font);}assert!(matched>0);}
