fn font_shape_original_table_inventory(){
 for source in semio_framework_2d_text_font_catalog::FONT_SOURCES.iter(){let r=FontReader::whole(source.bytes.0);let count=r.u16(4).unwrap();for index in 0..usize::from(count){let at=12+index*16;let tag=r.u32(at).unwrap();if !matches!(tag,0x47535542|0x47504f53){continue;}let base=r.u32(at+8).unwrap()as usize;let features=base+usize::from(r.u16(base+6).unwrap());let lookups=base+usize::from(r.u16(base+8).unwrap());let tags=(0..usize::from(r.u16(features).unwrap())).map(|i|String::from_utf8(r.u32(features+2+i*6).unwrap().to_be_bytes().to_vec()).unwrap()).collect::<Vec<_>>();let types=(0..usize::from(r.u16(lookups).unwrap())).map(|i|r.u16(lookups+usize::from(r.u16(lookups+2+i*2).unwrap())).unwrap()).collect::<Vec<_>>();}}
 let rows:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();for row in rows.as_array().unwrap(){let source=bytes(row["font"].as_str().unwrap());let face=rustybuzz::Face::from_slice(&source,0).unwrap();let mut buffer=rustybuzz::UnicodeBuffer::new();buffer.push_str(row["text"].as_str().unwrap());buffer.guess_segment_properties();buffer.set_direction(if row["direction"]=="rtl"{rustybuzz::Direction::RightToLeft}else{rustybuzz::Direction::LeftToRight});let shaped=rustybuzz::shape(&face,&[],buffer);let records=shaped.glyph_infos().iter().zip(shaped.glyph_positions()).map(|(glyph,position)|(glyph.glyph_id,glyph.cluster,position.x_advance,position.y_advance,position.x_offset,position.y_offset)).collect::<Vec<_>>();}
}
