fn font_shape_original_ligature_matches_rustybuzz(){let rows:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();let row=rows.as_array().unwrap().iter().find(|row|row["name"]=="Joined Emoji Profession").unwrap();let source=bytes(row["font"].as_str().unwrap());let mut admission=FontFaceAdmissionJob::new(source,FontOutlineLimits::default());while !admission.advance(7).unwrap().done{}let font=admission.take_result().unwrap();let parser=ttf_parser::Face::parse(&font.source,0).unwrap();let input=row["text"].as_str().unwrap().chars().map(|scalar|parser.glyph_index(scalar).unwrap().0).collect::<Vec<_>>();let mut buffer=rustybuzz::UnicodeBuffer::new();buffer.push_str(row["text"].as_str().unwrap());buffer.guess_segment_properties();let oracle=rustybuzz::shape(&rustybuzz::Face::from_slice(&font.source,0).unwrap(),&[],buffer);assert_eq!(oracle.glyph_infos().len(),1);let expected=oracle.glyph_infos()[0].glyph_id as u16;let mut plan=crate::FontLookupPlanCursor::new(font.face,true,*b"DFLT",&[*b"ccmp"],1000000000);while !plan.advance(&font.source,7).unwrap().done{}let output=plan.take_result().unwrap();for grant in [1,7,4096]{let mut matched=false;for lookup in output.iter().filter(|lookup|lookup.kind==4&&lookup.flags==0){let mut cursor=crate::ligature::FontLigatureCursor::new(font.face,*lookup,&input,0,1000000000);let mut work=0;loop{let p=cursor.advance(&font.source,&input,grant).unwrap();assert!(p.work-work<=grant as u64);work=p.work;if p.done{break;}assert!(cursor.result().is_err());}if let Some(result)=cursor.result().unwrap(){assert_eq!(result,crate::ligature::FontLigatureMatch{glyph:expected,consumed:input.len()});matched=true;}close(cursor);for stop in [0,1,2,7,20,40,100]{let mut cancelled=crate::ligature::FontLigatureCursor::new(font.face,*lookup,&input,0,1000000000);if stop>0{cancelled.advance(&font.source,&input,stop).unwrap();}cancelled.cancel();assert!(cancelled.result().is_err());close(cancelled);}}assert!(matched);}close(plan);close(output);close(input);close(admission);close(font);}
#[test]
fn font_shape_original_mark_matches_ttf_parser(){let mut admission=FontFaceAdmissionJob::new(bytes("🚀️anta/🏛️latin/📖️regular"),FontOutlineLimits::default());while !admission.advance(7).unwrap().done{}let font=admission.take_result().unwrap();let parser=ttf_parser::Face::parse(&font.source,0).unwrap();let mut plan=crate::FontLookupPlanCursor::new(font.face,false,*b"latn",&[*b"mark"],1000000000);while !plan.advance(&font.source,7).unwrap().done{}let output=plan.take_result().unwrap();let mut tested=0;for lookup in output.iter().filter(|lookup|lookup.kind==4&&lookup.flags==0){let parsed=parser.tables().gpos.unwrap().lookups.get(lookup.index).unwrap();let ttf_parser::gpos::PositioningSubtable::MarkToBase(table)=parsed.subtables.get::<ttf_parser::gpos::PositioningSubtable>(0).unwrap()else{panic!("Expected mark-to-base");};let(base,base_index)=(0..font.face.glyphs).find_map(|glyph|table.base_coverage.get(ttf_parser::GlyphId(glyph)).map(|index|(glyph,index))).unwrap();let(mark,mark_index)=(0..font.face.glyphs).find_map(|glyph|table.mark_coverage.get(ttf_parser::GlyphId(glyph)).map(|index|(glyph,index))).unwrap();let(class,anchor)=table.marks.get(mark_index).unwrap();let reference=table.anchors.get(base_index,class).unwrap();let expected=crate::mark::FontMarkAttachment{x:i32::from(reference.x)-i32::from(anchor.x),y:i32::from(reference.y)-i32::from(anchor.y)};for grant in [1,7,4096]{let mut cursor=crate::mark::FontMarkCursor::new(font.face,*lookup,base,mark,1000000000);let mut work=0;loop{let p=cursor.advance(&font.source,grant).unwrap();assert!(p.work-work<=grant as u64);work=p.work;if p.done{break;}assert!(cursor.result().is_err());}assert_eq!(cursor.result().unwrap(),Some(expected));close(cursor);for stop in [0,1,2,7,20,40,100]{let mut cancelled=crate::mark::FontMarkCursor::new(font.face,*lookup,base,mark,1000000000);if stop>0{cancelled.advance(&font.source,stop).unwrap();}cancelled.cancel();assert!(cancelled.result().is_err());close(cancelled);}}tested+=1;}assert!(tested>0);close(plan);close(output);close(admission);close(font);}
#[test]
fn font_shape_whole_cluster_original_source_selection(){use crate::face::*;use semio_framework_2d_text_font_shape_unicode::{*,normalize::NormalizedScalar,cluster::UnicodeCluster};let rows:serde_json::Value=serde_json::from_str(include_str!("../📇️face/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let mut unicode_admission=UnicodeDataAdmissionJob::new(UNICODE_BYTES.to_vec(),1000000);while !unicode_admission.advance(4096).unwrap().done{}let data=unicode_admission.take_result().unwrap();for row in rows.as_array().unwrap(){let mut catalog=semio_framework_2d_text_font_catalog::FontCatalogAdmissionJob::new(row["family"].as_str().unwrap(),400,FontOutlineLimits::default());while !catalog.advance(4096).unwrap().done{}let fonts=catalog.take_result().unwrap();let original=semio_framework_value::list::PagedList::<_,{usize::MAX}>::try_from_iter(row["text"].as_str().unwrap().char_indices().map(|(source_at,scalar)|NormalizedScalar{scalar:scalar as u32,source_at,combining_class:0})).unwrap();let parsed=fonts.iter().map(|font|ttf_parser::Face::parse(font.source.0,0).unwrap()).collect::<Vec<_>>();let resolve=|font:&ttf_parser::Face<'_>,value:&NormalizedScalar,index:usize|{if let Some(glyph)=font.glyph_index(char::from_u32(value.scalar).unwrap()){return Some(vec![glyph.0]);}if matches!(value.scalar,0x200d|0xfe0f){return Some(vec![0]);}row["alternates"][index].as_str().unwrap().chars().map(|scalar|font.glyph_index(scalar).map(|glyph|glyph.0)).collect::<Option<Vec<_>>>()};let expected=parsed.iter().position(|font|original.iter().enumerate().all(|(index,value)|resolve(font,value,index).is_some()));assert_eq!(expected.is_none(),row["refuses"].as_bool().unwrap());let cluster=UnicodeCluster{start:0,end:original.len()};for grant in [1,7,4096]{let mut cursor=FontClusterFaceCursor::new(data.layout,&data.source,&original,&fonts,cluster,0,FontOutlineLimits::default());let mut work=0;let result=loop{match cursor.advance(&data.source,&original,&fonts,grant){Ok(p)=>{assert!(p.work-work<=grant as u64);work=p.work;if p.done{break true;}assert!(cursor.result().is_err());},Err(error)=>{assert_eq!(error,"Unicode grapheme has no single admitted font source");break false;}}};assert_eq!(result,expected.is_some());if let Some(expected)=expected{let pointer=cursor.result().unwrap().glyphs.as_ptr();let output=cursor.take_result().unwrap();assert_eq!(output.face,expected);assert_eq!(output.glyphs.as_ptr(),pointer);let mapped=original.iter().enumerate().flat_map(|(index,source)|resolve(&parsed[expected],source,index).unwrap().into_iter().map(move|glyph|(glyph,source.source_at))).collect::<Vec<_>>();assert_eq!(output.glyphs.len(),mapped.len());for(value,(glyph,source_at))in output.glyphs.iter().zip(mapped){assert_eq!(value.glyph,glyph);assert_eq!(value.source_at,source_at);}close(cursor);close(output);}else{assert!(cursor.result().is_err());close(cursor);}}for stop in [0,1,2,7,20,100,1000]{let mut cursor=FontClusterFaceCursor::new(data.layout,&data.source,&original,&fonts,cluster,0,FontOutlineLimits::default());if stop>0{let _=cursor.advance(&data.source,&original,&fonts,stop);}let(_,physical)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cursor.cancel());assert_eq!((physical.requested_bytes,physical.released_bytes),(0,0));assert!(cursor.result().is_err());close(cursor);}drop(parsed);close(original);close(catalog);close(fonts);}close(unicode_admission);close(data);}
#[test]
fn font_shape_shared_repeated_gap_edits(){use crate::face::{FontClusterMapping,FontMappedScalar};let rows:serde_json::Value=serde_json::from_str(include_str!("../🧩️context/🪄️apply/🧪️tests/🧫️fixtures/🔣️.json")).unwrap();let mut limits=FontOutlineLimits::default();limits.max_glyphs=4096;let mut admission=FontFaceAdmissionJob::new(bytes(rows[0]["font"].as_str().unwrap()),limits);while !admission.advance(4096).unwrap().done{}let font=admission.take_result().unwrap();let parser=ttf_parser::Face::parse(&font.source,0).unwrap();for row in rows.as_array().unwrap(){let repeat=row["repeat"].as_u64().unwrap()as usize;let text=row["text"].as_str().unwrap().repeat(repeat);let original=||FontClusterMapping{face:0,glyphs:text.char_indices().map(|(source_at,scalar)|FontMappedScalar{glyph:parser.glyph_index(scalar).unwrap().0,scalar:scalar as u32,source_at:source_at/8*8,property:shape::unicode::UnicodeProperty{combining_class:0,category:28,bidi:0,joining:0,grapheme:12,flags:0,script:0}}).collect()};let mut buffer=rustybuzz::UnicodeBuffer::new();buffer.push_str(&text);buffer.guess_segment_properties();let oracle=rustybuzz::shape(&rustybuzz::Face::from_slice(&font.source,0).unwrap(),&[],buffer);let expected=oracle.glyph_infos().iter().map(|glyph|glyph.glyph_id as u16).collect::<Vec<_>>();assert_eq!(expected,vec![row["glyphs"][0].as_u64().unwrap()as u16;repeat]);let grants: &[usize]=if repeat>64{&[4096]}else{&[1,7,4096]};for &grant in grants{let mut cursor=crate::layout::FontClusterLayoutCursor::new(font.face,original(),limits);let mut work=0;loop{let(progress,physical)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cursor.advance(&font.source,grant).unwrap());assert!(!physical.overflowed);assert_eq!(physical.released_bytes,0);assert!(progress.work-work<=grant as u64);work=progress.work;if progress.done{break;}}assert!(work<(repeat*20000+4096*8)as u64);let pointer=cursor.result().unwrap().glyphs.as_ptr();let(output,physical)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cursor.take_result().unwrap());assert_eq!((physical.requested_bytes,physical.released_bytes),(0,0));assert_eq!(output.glyphs.as_ptr(),pointer);assert_eq!(output.glyphs.iter().map(|glyph|glyph.glyph).collect::<Vec<_>>(),expected);close_with_items(cursor,if repeat>64{64}else{1});assert_eq!(output.glyphs.as_ptr(),pointer);close(output);}for stop in row["stops"].as_array().unwrap(){let mut cursor=crate::layout::FontClusterLayoutCursor::new(font.face,original(),limits);let stop=stop.as_u64().unwrap()as usize;if stop>0{cursor.advance(&font.source,stop).unwrap();}let(_,physical)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cursor.cancel());assert_eq!((physical.requested_bytes,physical.released_bytes),(0,0));assert!(cursor.result().is_err());close(cursor);}}close(admission);close(font);}
